// Lazy: constructing the OpenAI client at module load throws "Missing
// credentials" if neither AI_INTEGRATIONS_OPENAI_API_KEY nor OPENAI_API_KEY is
// set — and because this module is imported at boot, that crash takes the WHOLE
// server down before it can listen, so Render's /api/health check fails and the
// deploy is rolled back (the old build keeps serving). Deferring construction to
// first use means a missing/rotated key only degrades AI features (Rizz etc.),
// never downs the site or blocks a deploy. The Proxy keeps every `openai.x` call
// site unchanged.
let _openaiClient: OpenAI | null = null;
function getOpenAI(): OpenAI {
  if (!_openaiClient) {
    _openaiClient = new OpenAI({
      apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY || process.env.OPENAI_API_KEY,
      baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
    });
  }
  return _openaiClient;
}
const openai = new Proxy({} as OpenAI, {
  get(_t, prop) {
    const c = getOpenAI();
    const v = (c as any)[prop];
    return typeof v === "function" ? v.bind(c) : v;
  },
});

// ============================================
// VALIDATION HELPERS
// ============================================

// Centralized Zod validation error formatter — never leaks stack traces
function formatZodError(error: z.ZodError): { error: string; details: string[] } {
  return {
    error: "Validation failed",
    details: error.errors.map(e => `${e.path.join(".") || "body"}: ${e.message}`),
  };
}

// Safe error message — in production, only expose stack-safe messages for 500s
function safeError(err: any): string {
  if (process.env.NODE_ENV === "production") {
    return "Internal server error";
  }
  return err?.message || "Internal server error";
}

// Builds the public base URL for shareable referral links. Behind Render's
// proxy, req.protocol can report "http" even though the site is served over
// HTTPS, which would mint insecure share links. Prefer APP_URL; otherwise use
// https for a real domain or an x-forwarded-proto:https request, falling back
// to req.protocol only for localhost dev. Result e.g. https://braintrack.tech
function referralBaseUrl(req: any): string {
  if (process.env.APP_URL) return process.env.APP_URL.replace(/\/+$/, "");
  const host = req.get("host") || "";
  const xfProto = String(req.headers["x-forwarded-proto"] || "")
    .split(",")[0]
    .trim()
    .toLowerCase();
  const isLocal = /^(localhost|127\.0\.0\.1|\[::1\])(:\d+)?$/i.test(host);
  const proto = xfProto === "https" || (!!host && !isLocal) ? "https" : req.protocol || "http";
  return `${proto}://${host}`;
}

// Validate a South African ID number: exactly 13 digits, a valid YYMMDD date
// in positions 1-6, and a correct Luhn (mod-10) check digit. Citizenship and
// gender digits are intentionally NOT validated.
function isValidSaIdNumber(raw: string): boolean {
  const id = (raw ?? "").trim();
  if (!/^\d{13}$/.test(id)) return false;

  // Date of birth: YYMMDD (century-agnostic; month 01-12, day 01-31).
  const month = parseInt(id.slice(2, 4), 10);
  const day = parseInt(id.slice(4, 6), 10);
  if (month < 1 || month > 12) return false;
  if (day < 1 || day > 31) return false;

  // Luhn check across all 13 digits.
  let sum = 0;
  let alternate = false;
  for (let i = id.length - 1; i >= 0; i--) {
    let n = id.charCodeAt(i) - 48; // '0' = 48
    if (alternate) {
      n *= 2;
      if (n > 9) n -= 9;
    }
    sum += n;
    alternate = !alternate;
  }
  return sum % 10 === 0;
}

const onboardingSchema = z.object({
  learningStyle: z.string(),
  studyPreference: z.string(),
  focusDuration: z.number(),
  challenges: z.array(z.string()),
  goals: z.array(z.string()),
  // Normalise to the short form the DB CHECK constraint requires
  // (onboarding_results_preferred_language_short_form: 'en' | 'af'). Accepts
  // 'en'/'af' or long forms 'english'/'afrikaans' (any case) from the client.
  preferredLanguage: z
    .string()
    .default("en")
    .transform((v) => (v.toLowerCase().startsWith("af") ? "af" : "en")),
  rawAnswersJson: z.any().optional(),
  traitsJson: z.any().optional(),
  recommendationsJson: z.any().optional(),
  varkPrimary: z.enum(["visual", "auditory", "read", "kinesthetic"]).optional(),
  varkSecondary: z.enum(["visual", "auditory", "read", "kinesthetic"]).nullable().optional(),
  // Task #43 — School linking + parent contact captured during onboarding.
  schoolName: z.string().trim().min(1).max(200).optional(),
  schoolId: z.number().int().positive().optional(),
  grade: z.number().int().min(8).max(12).optional(),
  parentEmail: z.string().trim().email().max(200).optional(),
  // Learner identity fields captured during onboarding.
  firstName: z.string().trim().min(1).max(100).optional(),
  lastName: z.string().trim().min(1).max(100).optional(),
  // South African ID number: exactly 13 digits, valid YYMMDD date in the
  // first 6 positions, and a valid Luhn check digit. SENSITIVE — persisted to
  // users.idNumber and never returned to any client.
  idNumber: z
    .string()
    .trim()
    .optional()
    .refine((v) => v === undefined || isValidSaIdNumber(v), {
      message: "Invalid South African ID number",
    }),
  // Date of birth (yyyy-mm-dd). NEVER persisted in plaintext — a salted
  // SHA-256 (dobHash) + derived isMinor flag are stored on the users row and
  // the raw value is discarded. Cross-checked against the ID number's YYMMDD
  // prefix in the handler.
  dateOfBirth: z
    .string()
    .trim()
    .regex(/^\d{4}-\d{2}-\d{2}$/, "Date of birth must be yyyy-mm-dd")
    .optional()
    .refine((v) => {
      if (v === undefined) return true;
      const d = new Date(`${v}T00:00:00Z`);
      return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === v;
    }, { message: "Invalid date of birth" }),
}).strip();

