  // GET /api/admin/reports/dbe-coverage — per-subject DBE content coverage.
  //
  // Powers the "DBE Content Coverage" report on the admin dashboard: for every
  // subject present in dbe_verbatim_questions, how many questions have passed
  // the release gate (released_at IS NOT NULL) versus how many are ingested in
  // total. Subjects at 0% are the operational signal — those are ingested but
  // learner-invisible.
  app.get("/api/admin/reports/dbe-coverage", isAuthenticated, requireRole("admin"), async (_req: any, res) => {
    try {
      const result = await db.execute(sql`
        SELECT
          subject,
          COUNT(*)::int                                            AS total,
          COUNT(*) FILTER (WHERE released_at IS NOT NULL)::int     AS released
        FROM dbe_verbatim_questions
        GROUP BY subject
        ORDER BY
          (COUNT(*) FILTER (WHERE released_at IS NOT NULL))::float / NULLIF(COUNT(*), 0) ASC NULLS FIRST,
          COUNT(*) DESC
      `);

      const subjects = result.rows.map((r: any) => {
        const total = Number(r.total ?? 0);
        const released = Number(r.released ?? 0);
        return {
          subject: String(r.subject ?? "Unknown"),
          total,
          released,
          pct: total > 0 ? Math.round((released / total) * 1000) / 10 : 0,
        };
      });

      const totals = subjects.reduce(
        (acc, s) => ({ total: acc.total + s.total, released: acc.released + s.released }),
        { total: 0, released: 0 },
      );

      return res.json({
        subjects,
        totals: {
          ...totals,
          pct: totals.total > 0 ? Math.round((totals.released / totals.total) * 1000) / 10 : 0,
          subjectCount: subjects.length,
          zeroReleasedCount: subjects.filter((s) => s.released === 0).length,
        },
        fetchedAt: new Date().toISOString(),
      });
    } catch (err: any) {
      console.error("[admin/reports/dbe-coverage] error:", err);
      return res.status(500).json({ error: safeError(err) });
    }
  });

  // GET /api/admin/reports/subscription-funnel — subscription status breakdown.
  //
  // Powers the "Subscription Funnel" report on the admin dashboard. Every
  // status actually present in the subscriptions table is returned (nothing is
  // hardcoded), plus explicit zero rows for the four canonical funnel stages so
  // the chart keeps its shape when a stage has no rows yet.
  app.get("/api/admin/reports/subscription-funnel", isAuthenticated, requireRole("admin"), async (_req: any, res) => {
    try {
      // Demo accounts excluded — they carry a seeded subscription so the demo
      // dashboards render, which must not shift the funnel.
      const result = await db.execute(sql`
        SELECT s.status, COUNT(*)::int AS count
        FROM subscriptions s
        JOIN users u ON u.id = s.user_id
        WHERE u.is_demo = false
        GROUP BY s.status
      `);

      const observed = new Map<string, number>();
      for (const r of result.rows as any[]) {
        observed.set(String(r.status ?? "unknown"), Number(r.count ?? 0));
      }

      // Canonical funnel order. Any status found in the table but not listed
      // here is appended afterwards so nothing is silently dropped.
      const CANONICAL = ["trial", "active", "past_due", "cancelled"];
      const stages = [
        ...CANONICAL.map((status) => ({ status, count: observed.get(status) ?? 0 })),
        ...Array.from(observed.entries())
          .filter(([status]) => !CANONICAL.includes(status))
          .map(([status, count]) => ({ status, count })),
      ];

      const total = stages.reduce((n, s) => n + s.count, 0);

      return res.json({
        stages,
        total,
        // Share of all subscriptions that are currently paying.
        activeRate: total > 0
          ? Math.round(((observed.get("active") ?? 0) / total) * 1000) / 10
          : 0,
        fetchedAt: new Date().toISOString(),
      });
    } catch (err: any) {
      console.error("[admin/reports/subscription-funnel] error:", err);
      return res.status(500).json({ error: safeError(err) });
    }
  });

  // GET /api/admin/push/daily-focus-log — daily roll-up of focus-push delivery
  // Optional query params: date (YYYY-MM-DD, defaults to today SAST), limit (default 60)
  app.get("/api/admin/push/daily-focus-log", isAuthenticated, requireRole("admin"), async (req: any, res) => {
    try {
      const SAST_OFFSET_MS = 2 * 60 * 60 * 1000;
      const todaySast = new Date(Date.now() + SAST_OFFSET_MS).toISOString().slice(0, 10);
      const dateParam = typeof req.query.date === "string" && /^\d{4}-\d{2}-\d{2}$/.test(req.query.date)
        ? req.query.date
        : todaySast;
      const limitParam = Math.min(Math.max(parseInt(String(req.query.limit ?? "60"), 10) || 60, 1), 500);

      const rollup = await db.execute(sql`
        SELECT
          sent_date,
          COUNT(*)                                            AS total_attempts,
          COUNT(*) FILTER (WHERE channel = 'learner')        AS learner_attempts,
          COUNT(*) FILTER (WHERE channel = 'parent')         AS parent_attempts,
          COUNT(*) FILTER (WHERE success = true)             AS succeeded,
          COUNT(*) FILTER (WHERE success = false AND error IS NOT NULL) AS failed,
          COUNT(*) FILTER (WHERE channel = 'learner' AND success = true) AS learners_reached,
          COUNT(*) FILTER (WHERE channel = 'parent'  AND success = true) AS parents_reached
        FROM daily_focus_push_log
        WHERE sent_date = ${dateParam}
        GROUP BY sent_date
      `);

      const rows = await db.execute(sql`
        SELECT
          l.user_id,
          u.email,
          u.first_name,
          u.last_name,
          l.channel,
          l.payload_tag,
          l.success,
          l.error,
          l.created_at
        FROM daily_focus_push_log l
        LEFT JOIN users u ON u.id = l.user_id
        WHERE l.sent_date = ${dateParam}
        ORDER BY l.created_at DESC
        LIMIT ${limitParam}
      `);

      res.json({
        date: dateParam,
        summary: rollup.rows[0] ?? {
          total_attempts: 0,
          learner_attempts: 0,
          parent_attempts: 0,
          succeeded: 0,
          failed: 0,
          learners_reached: 0,
          parents_reached: 0,
        },
        rows: rows.rows,
      });
    } catch (err: any) {
      console.error("[GET /api/admin/push/daily-focus-log]", err.message);
      res.status(500).json({ error: safeError(err) });
    }
  });

  // GET /api/admin/push/daily-focus-log/trend — 7-day rolling delivery trend
  // Query param: days (default 7, max 30)
  app.get("/api/admin/push/daily-focus-log/trend", isAuthenticated, requireRole("admin"), async (req: any, res) => {
    try {
      const SAST_OFFSET_MS = 2 * 60 * 60 * 1000;
      const daysParam = Math.min(Math.max(parseInt(String(req.query.days ?? "7"), 10) || 7, 1), 30);
      const todaySast = new Date(Date.now() + SAST_OFFSET_MS).toISOString().slice(0, 10);

      const trend = await db.execute(sql`
        WITH date_series AS (
          SELECT generate_series(
            (${todaySast}::date - (${daysParam} - 1) * INTERVAL '1 day'),
            ${todaySast}::date,
            INTERVAL '1 day'
          )::date AS day
        )
        SELECT
          ds.day::text AS date,
          COALESCE(COUNT(*) FILTER (WHERE l.channel = 'learner' AND l.success = true), 0) AS learners_reached,
          COALESCE(COUNT(*) FILTER (WHERE l.success = false AND l.error IS NOT NULL), 0) AS failed
        FROM date_series ds
        LEFT JOIN daily_focus_push_log l ON l.sent_date = ds.day
        GROUP BY ds.day
        ORDER BY ds.day ASC
      `);

      res.json({ days: daysParam, trend: trend.rows });
    } catch (err: any) {
      console.error("[GET /api/admin/push/daily-focus-log/trend]", err.message);
      res.status(500).json({ error: safeError(err) });
    }
  });

