      await storage.insertAuditLog({
        userId: adminUserId,
        action: "billing.mark_lapsed",
        target: "subscription",
        metadata: { targetUserId, note: note || null },
      });
      res.json({ ok: true, status: "lapsed", userId: targetUserId });
